{"command":"cat > main.c <<'EOF'
#include <stdio.h>
#include <string.h>
int main(int argc, char **argv) {
    int show = 0;
    if (argc == 1) show = 1;
    for (int i = 1; i < argc; ++i) {
        if (strcmp(argv[i], "-h") == 0 || strcmp(argv[i], "--help") == 0) { show = 1; break; }
        if (strcmp(argv[i], "help") == 0) { show = 1; break; }
    }
    if (show) {
        const char *s =
"usage: duc <cmd> [options] [args]\n\n"
"Available subcommands:\n\n"
"  help      : Show help\n"
"  histogram : Dump histogram of file sizes found.\n"
"  index     : Scan the filesystem and generate the Duc index\n"
"  info      : Dump database info\n"
"  ls        : List sizes of directory\n"
"  topn      : Dump N largest files in DB.\n"
"  xml       : Dump XML output\n"
"  json      : Dump JSON output\n"
"  graph     : Generate a sunburst graph for a given path\n"
"  cgi       : CGI interface wrapper\n"
"  gui       : Interactive X11 graphical interface\n"
"  ui        : Interactive ncurses user interface\n\n"
"Global options:\n"
"       --debug               increase verbosity to debug level\n"
"  -h,  --help                show help\n"
"  -q,  --quiet               quiet mode, do not print any warning\n"
"  -v,  --verbose             increase verbosity\n"
"       --version             output version information and exit\n\n"
"Use 'duc help <subcommand>' or 'duc <subcommand> -h' for a complete list of all\n"
"options and detailed description of the subcommand.\n\n"
"Use 'duc help --all' for a complete list of all options for all subcommands.\n";
        fputs(s, stdout);
        return 0;
    }
    /* Default: print same usage for any other input */
    const char *s = "usage: duc <cmd> [options] [args]\n\nAvailable subcommands:\n\n  help      : Show help\n  histogram : Dump histogram of file sizes found.\n  index     : Scan the filesystem and generate the Duc index\n  info      : Dump database info\n  ls        : List sizes of directory\n  topn      : Dump N largest files in DB.\n  xml       : Dump XML output\n  json      : Dump JSON output\n  graph     : Generate a sunburst graph for a given path\n  cgi       : CGI interface wrapper\n  gui       : Interactive X11 graphical interface\n  ui        : Interactive ncurses user interface\n\nGlobal options:\n       --debug               increase verbosity to debug level\n  -h,  --help                show help\n  -q,  --quiet               quiet mode, do not print any warning\n  -v,  --verbose             increase verbosity\n       --version             output version information and exit\n\nUse 'duc help <subcommand>' or 'duc <subcommand> -h' for a complete list of all\noptions and detailed description of the subcommand.\n\nUse 'duc help --all' for a complete list of all options for all subcommands.\n";
    fputs(s, stdout);
    return 0;
}
EOF

cat > compile.sh <<'EOF'
#!/bin/sh
set -e
cc -O2 main.c -o executable
chmod +x compile.sh
# Make the produced executable non-world-writable
chmod 755 executable
EOF

cat > .gitignore <<'EOF'
executable
EOF

chmod +x compile.sh

# compile to test
./compile.sh

# show the produced output
./executable --help
./executable
EOF"}

